import { createRouter, createWebHistory } from 'vue-router';
import Routes from '@shell/config/router/routes';
import { installNavigationGuards } from '@shell/config/router/navigation-guards';
import { extendRouter as ER } from '@shell/plugins/extend-router';

export const routerOptions = {
  history:  createWebHistory(process.env.routerBase || '/'),
  // Note: router base comes from the ROUTER_BASE env var
  base:     process.env.routerBase || '/',
  routes:   Routes,
  fallback: false,
};

function toRealUrl(url) {
  if (url.includes('/console/')) {
    const match = url.match(/\/harvester\/c\/([^/]+)\/console\/(.+)$/);

    if (match) {
      return `/harvester/c/${ match[1] }/console/${ match[2] }`;
    }

    return url.replace('/skylus-essentials', '/harvester');
  }

  return url
    .replace('/skylus-essentials', '/harvester')
    .replaceAll('network.skylusessentials-hci.io.', 'network.harvesterhci.io.')
    .replaceAll('skylusessentials-hci.io.', 'harvesterhci.io.');
}

function toDisplayUrl(url) {
  if (url.includes('/console/')) {
    return url;
  }

  return url
    .replace('/harvester', '/skylus-essentials')
    .replaceAll('network.harvesterhci.io.', 'network.skylusessentials-hci.io.')
    .replaceAll('harvesterhci.io.', 'skylusessentials-hci.io.');
}

export function extendRouter(config, context) {
  const base = (config._app && config._app.basePath) || routerOptions.base;
  const currentUrl = window.location.pathname + window.location.search + window.location.hash;
  const realUrl = toRealUrl(currentUrl);

  if (realUrl !== currentUrl) {
    window.history.replaceState(window.history.state, '', realUrl);
  }

  const router = createRouter({
    ...routerOptions,
    base,
  });

  router.afterEach(() => {
    const currentUrl = window.location.pathname + window.location.search + window.location.hash;
    const displayUrl = toDisplayUrl(currentUrl);

    if (displayUrl !== currentUrl) {
      window.history.replaceState(window.history.state, '', displayUrl);
    }
  });

  ER(router);

  installNavigationGuards(router, context);

  return router;
}